import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.DAK02U1-.js";const f=JSON.parse('{"title":"Format","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Format | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/format"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/format"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/format"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/format"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/format"}]]},"headers":[],"relativePath":"clice/cli/format.md","filePath":"en/clice/cli/format.md","lastUpdated":1789451490000}'),s={name:"clice/cli/format.md"};function r(c,e,n,l,h,d){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>clice format</code> runs clang-format over the files of a workspace, several processes at a time, with the <code>.clang-format</code> configuration the tree already has. clice adds no style settings of its own: the style comes from clang-format&#39;s own discovery, the nearest <code>.clang-format</code> above each file.</p><p><strong>Usage</strong>: <code>clice format [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--check] [--clang-format &lt;path&gt;] [--jobs &lt;n&gt;] [&lt;path&gt;...]</code></p><p>Without paths it formats the build&#39;s own files: every translation unit of the compilation database and every file with a C-family suffix they include that sits inside the workspace, outside the build trees (a directory below the root holding a compilation database, where a build generates or fetches sources), outside the system include directories of their commands and outside the cache directory. A directory argument narrows that set to the files under it; a file argument with a C-family suffix is formatted whether or not the build knows it. Paths are relative to the workspace. A rule in <code>clice.toml</code> with <code>format = false</code> keeps matching files out, for example a vendored library or generated sources:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;third_party/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gen/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>Files are rewritten in place; a symlinked source is rewritten at its target, which has to sit inside the workspace as well. <code>--check</code> rewrites nothing and prints what clang-format would change, one diagnostic per place, then how many files need formatting. <code>--clang-format</code> names the executable to run, by default the <code>clang-format</code> found in <code>PATH</code>.</p><p>Exit codes: <code>0</code> when every file is formatted (or, with <code>--check</code>, nothing would change), <code>1</code> when <code>--check</code> found files to format, <code>2</code> when the run could not complete: clang-format was not found or failed on a file, the workspace, its configuration or a compilation database could not be loaded, or the requested configuration does not exist.</p>`,8)])])}const m=t(s,[["render",r]]);export{f as __pageData,m as default};
